void strip_newline(char *s) {
    int n = (int)strlen(s);
    while (n > 0 && (s[n-1] == '\n' || s[n-1] == '\r')) {
        s[n-1] = '\0';
        n--;
    }
}

int is_prefix(const char *s, int *exp) {
    int i;
    for (i = 0; i < (int)(sizeof(prefixes)/sizeof(prefixes[0])); i++) {
        if (strcmp(s, prefixes[i].name) == 0) {
            *exp = prefixes[i].exp;
            return 1;
        }
    }
    return 0;
}

int main(void) {
    char line[1024];
    if (!fgets(line, sizeof(line), stdin)) return 0;
    strip_newline(line);

    char *tok[3];
    int cnt = 0;
    char *p = strtok(line, " \t");
    while (p && cnt < 3) {
        tok[cnt++] = p;
        p = strtok(NULL, " \t");
    }

    if (cnt < 2) return 0;

    char *num = tok[0];
    char *unit;
    int prefix_exp = 0;

    if (cnt == 3) {
        is_prefix(tok[1], &prefix_exp);
        unit = tok[2];
    } else {
        unit = tok[1];
    }

    int len = (int)strlen(num);
    int dot = -1;
    int i;
    for (i = 0; i < len; i++) {
        if (num[i] == '.') {
            dot = i;
            break;
        }
    }

    char digits[1024];
    int dlen = 0;
    for (i = 0; i < len; i++) {
        if (isdigit((unsigned char)num[i])) {
            digits[dlen++] = num[i];
        }
    }
    digits[dlen] = '\0';

    int first_nonzero = -1;
    for (i = 0; i < dlen; i++) {
        if (digits[i] != '0') {
            first_nonzero = i;
            break;
        }
    }

    if (first_nonzero == -1) {
        printf("0 * 10^0 %s\n", unit);
        return 0;
    }

    int before_dot = (dot == -1) ? len : dot;
    int exponent;

    if (dot == -1) {
        exponent = before_dot - 1 - first_nonzero;
    } else {
        int nonzero_before_dot = 0;
        for (i = 0; i < dot; i++) {
            if (isdigit((unsigned char)num[i]) && num[i] != '0') {
                nonzero_before_dot = 1;
                break;
            }
        }

        if (nonzero_before_dot) {
            exponent = before_dot - 1 - first_nonzero;
        } else {
            int frac_pos = 0;
            for (i = dot + 1; i < len; i++) {
                if (isdigit((unsigned char)num[i])) {
                    if (num[i] != '0') break;
                    frac_pos++;
                }
            }
            exponent = -(frac_pos + 1);
        }
