        mantissa[mpos++] = '.';
        for (i = first_nonzero + 1; i < dlen; i++) {
            mantissa[mpos++] = digits[i];
        }
    }
    mantissa[mpos] = '\0';

    printf("%s * 10^%d %s\n", mantissa, exponent, unit);

    return 0;
