        String digits;   // all digits without decimal point
        int scale;       // number of digits after decimal point in original number
        boolean zero;
        int firstNonZeroIndex; // in digits, -1 if zero
        int significantCount;  // count of significant figures
    }

    static Map<String, Integer> prefixExp = new HashMap<>();

    static {
        prefixExp.put("yotta", 24);
        prefixExp.put("zetta", 21);
        prefixExp.put("exa", 18);
        prefixExp.put("peta", 15);
        prefixExp.put("tera", 12);
        prefixExp.put("giga", 9);
        prefixExp.put("mega", 6);
        prefixExp.put("kilo", 3);
        prefixExp.put("hecto", 2);
        prefixExp.put("deca", 1);
        prefixExp.put("deci", -1);
        prefixExp.put("centi", -2);
        prefixExp.put("milli", -3);
        prefixExp.put("micro", -6);
        prefixExp.put("nano", -9);
        prefixExp.put("pico", -12);
        prefixExp.put("femto", -15);
        prefixExp.put("ato", -18);
        prefixExp.put("zepto", -21);
        prefixExp.put("yocto", -24);
    }

    static ParsedNumber parseNumber(String s) {
        ParsedNumber p = new ParsedNumber();
        int dot = s.indexOf('.');
        String intPart, fracPart;
        if (dot >= 0) {
            intPart = s.substring(0, dot);
            fracPart = s.substring(dot + 1);
        } else {
            intPart = s;
            fracPart = "";
        }

        p.digits = intPart + fracPart;
        p.scale = fracPart.length();

        p.firstNonZeroIndex = -1;
        for (int i = 0; i < p.digits.length(); i++) {
            if (p.digits.charAt(i) != '0') {
                p.firstNonZeroIndex = i;
                break;
            }
        }
        p.zero = (p.firstNonZeroIndex == -1);

        if (p.zero) {
            p.significantCount = 1;
            return p;
        }

        if (dot >= 0) {
            // Decimal present: all digits from first non-zero to end are significant
            p.significantCount = p.digits.length() - p.firstNonZeroIndex;
        } else {
            // No decimal: trailing zeros are not significant
            int lastNonZero = -1;
            for (int i = p.digits.length() - 1; i >= 0; i--) {
                if (p.digits.charAt(i) != '0') {
                    lastNonZero = i;
                    break;
                }
            }
            p.significantCount = lastNonZero - p.firstNonZeroIndex + 1;
        }
        return p;
    }

    static String buildMantissa(ParsedNumber p) {
        if (p.zero) return "0";

        String sig;
        if (p.significantCount == 1) {
            sig = String.valueOf(p.digits.charAt(p.firstNonZeroIndex));
        } else {
            sig = p.digits.substring(p.firstNonZeroIndex, p.firstNonZeroIndex + p.significantCount);
        }

        if (sig.length() == 1) return sig;
        return sig.charAt(0) + "." + sig.substring(1);
    }

    static int baseExponent(ParsedNumber p) {
        if (p.zero) return 0;
        return (p.digits.length() - p.scale - 1) - p.firstNonZeroIndex;
    }

    static String singularize(String unit) {
        if (unit.endsWith("s") && unit.length() > 1) {
            return unit.substring(0, unit.length() - 1);
        }
        return unit;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        StringBuilder all = new StringBuilder();
        while ((line = br.readLine()) != null) {
            if (all.length() > 0) all.append(' ');
            all.append(line.trim());
        }

        String input = all.toString().trim();
        if (input.isEmpty()) return;

        String[] parts = input.split("\\s+");
        String numberStr = parts[0];

        String prefix = "";
        String unit;
        if (parts.length == 2) {
            unit = parts[1];
        } else {
            prefix = parts[1].toLowerCase();
            unit = parts[2];
        }

        int prefixPower = prefixExp.getOrDefault(prefix, 0);
        unit = singularize(unit);

        ParsedNumber parsed = parseNumber(numberStr);
        String mantissa = buildMantissa(parsed);
        int exponent = baseExponent(parsed) + prefixPower;

        System.out.println(mantissa + " * 10^" + exponent + " " + unit);
    }
}
